export * as Certificate from "./certificate.js";
import { Schema } from "effect";
import { Newtype } from "./newtype.js";
export class ID extends Newtype()("CertificateID", Schema.String) {
}
export const Token = Schema.String.pipe(Schema.brand("ChallengeToken"));
export class StateChallenge extends Schema.Class("Certificate/StateChallenge")({
    type: Schema.Literal("challenge"),
    token: Schema.String,
    key: Schema.String,
}) {
}
export class StateIssuing extends Schema.Class("Certificate/StateIssuing")({
    type: Schema.Literal("issuing"),
}) {
}
export class StateReady extends Schema.Class("Certificate/StateReady")({
    type: Schema.Literal("ready"),
    certificate: Schema.String,
    chain: Schema.String,
    expiry: Schema.String,
}) {
}
export class StateFailed extends Schema.Class("Certificate/StateFailed")({
    type: Schema.Literal("failed"),
    reason: Schema.String,
}) {
}
export const State = Schema.Union([StateChallenge, StateIssuing, StateReady, StateFailed]);
export class Info extends Schema.Class("Certificate")({
    id: ID,
    state: State,
}) {
}
